#!/bin/sh
# Build gekko as an Erlang shipment and install a `gekko` launcher on PATH.
# Usage: scripts/install.sh [bin_dir]   (default: ~/.local/bin)
set -eu

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
BIN_DIR="${1:-$HOME/.local/bin}"

cd "$ROOT"
gleam export erlang-shipment

mkdir -p "$BIN_DIR"
cat > "$BIN_DIR/gekko" <<EOF
#!/bin/sh
# Generated by $ROOT/scripts/install.sh
exec "$ROOT/build/erlang-shipment/entrypoint.sh" run "\$@"
EOF
chmod +x "$BIN_DIR/gekko"
echo "Installed $BIN_DIR/gekko (re-run scripts/install.sh after changing gekko's source)"
